CREATE TABLE "Project" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "width" INTEGER NOT NULL DEFAULT 1024, "height" INTEGER NOT NULL DEFAULT 1024, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Project_pkey" PRIMARY KEY ("id"));
CREATE TABLE "EffectRecipe" ("id" TEXT NOT NULL, "projectId" TEXT NOT NULL, "name" TEXT NOT NULL, "effects" JSONB NOT NULL, "randomSeed" INTEGER, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "EffectRecipe_pkey" PRIMARY KEY ("id"), CONSTRAINT "EffectRecipe_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "EffectRecipe_projectId_idx" ON "EffectRecipe"("projectId");
